/* Execute generated bytes using the existing, unmodified native emulator CPU. */
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "hw/z80.h"
#include "unsigned-engine.h"
static uint8_t memory[65536];static device_t ram;
void vtimer_tick(uint64_t ignored){(void)ignored;}
uint64_t vtimer_stall_bus(uint64_t ignored,const bool *requested){(void)ignored;(void)requested;return 0;}
static uint8_t rd(device_t *d,uint32_t at){(void)d;return memory[(uint16_t)at];}
static void wr(device_t *d,uint32_t at,uint8_t v){(void)d;memory[(uint16_t)at]=v;}
int mmu_init(mmu_t *m){memset(m,0,sizeof(*m));return 0;}
static void put(uint16_t at,uint32_t v){unsigned i;for(i=0;i<4;++i)memory[at+i]=(uint8_t)(v>>(8*i));}
static uint32_t get(uint16_t at){uint32_t v=0;unsigned i;for(i=0;i<4;++i)v|=(uint32_t)memory[at+i]<<(8*i);return v;}
static z80 cpu;
static uint16_t run(uint8_t op,uint32_t left,uint32_t right) {
    unsigned i;z80_reset(&cpu);cpu.pc=0x8000;cpu.sp=0xf000;cpu.ix=0x1234;cpu.iy=0x5678;
    cpu.a=op;cpu.d=0x60;cpu.e=0;cpu.h=0x60;cpu.l=0x10;cpu.b=0x61;cpu.c=0;
    put(0x6000,left);put(0x6010,right);memory[0xf000]=0;memory[0xf001]=0x70;
    if(op&0x40){cpu.d=(uint8_t)(left>>8);cpu.e=(uint8_t)left;}
    if(op&0x80){cpu.h=(uint8_t)(right>>8);cpu.l=(uint8_t)right;}
    for(i=0;i<100000&&cpu.pc!=0x7000&&cpu.pc!=TEST_ERROR;++i)z80_step(&cpu);
    assert(i<100000);
    if(cpu.pc==0x7000){assert(cpu.ix==0x1234&&cpu.iy==0x5678&&cpu.sp==0xf002);}
    return ((uint16_t)cpu.h<<8)|cpu.l;
}
static uint32_t random_state=0x21749683;
static uint32_t random32(void){random_state=random_state*1664525u+1013904223u;return random_state;}
int main(void) {
    unsigned i,j,count=0;uint32_t a,b,want,got;uint16_t hl;
    device_init_mem(&ram,"flat test memory",rd,wr,sizeof(memory));memset(&cpu,0,sizeof(cpu));
    for(i=0;i<4;++i){cpu.mmu.pages[i]=(uint8_t)i;cpu.mmu.vpages[i].dev=&ram;}
    memcpy(memory+0x8000,unsigned_code,sizeof(unsigned_code));
    for(i=0;i<sizeof(unsigned_relocations)/sizeof(unsigned_relocations[0]);++i){j=unsigned_relocations[i];hl=memory[0x8000+j]|((uint16_t)memory[0x8001+j]<<8);hl+=0x8000;memory[0x8000+j]=(uint8_t)hl;memory[0x8001+j]=(uint8_t)(hl>>8);}
    for(i=0;i<2000;++i) {
        a=i<8?(uint32_t[]){0,1,255,65535,65536,0x7fffffff,0x80000000,0xffffffff}[i]:random32();b=random32();
        for(j=0;j<11;++j){
            uint32_t rhs=j==8||j==9?b%40:b;
            switch(j){case 0:want=a+rhs;break;case 1:want=a-rhs;break;case 2:want=a*rhs;break;case 3:want=a/rhs;break;case 4:want=a%rhs;break;case 5:want=a&rhs;break;case 6:want=a|rhs;break;case 7:want=a^rhs;break;case 8:want=rhs<32?a<<rhs:0;break;case 9:want=rhs<32?a>>rhs:0;break;default:want=(uint16_t)(a<rhs?-1:a>rhs?1:0);}
            hl=run((uint8_t)j,a,rhs);got=j==10?hl:get(hl);
            if(got!=want){fprintf(stderr,"op%u %08x %08x got%08x want%08x\n",j,a,rhs,got,want);return 1;}++count;
        }
        hl=run(11,0,a);assert(get(hl)==~a);++count;
        hl=run(14,0,a);{char text[12];snprintf(text,sizeof(text),"%u",a);assert(memory[hl]==strlen(text));assert(!memcmp(memory+hl+1,text,strlen(text)));++count;}
    }
    hl=run(0xc0,65535,1);assert(get(hl)==65536);++count;
    hl=run(0xf0,65535,1);assert(get(hl)==0);++count;
    run(3,1,0);assert(cpu.pc==TEST_ERROR&&cpu.a==2&&cpu.b==2);++count;
    run(13,0,65536);assert(cpu.pc==TEST_ERROR&&cpu.a==0x91);++count;
    printf("%u generated unsigned engine assertions passed\n",count);return 0;
}
